// Factory presets of Zedok Hybrid. Values are in real units (Hz, ms, ...) or choice labels. Level matching is done by presetgen.
#include "presetgen.h"
using VV = std::vector<V>;
static VV operator+(VV a, const VV& b) { a.insert(a.end(), b.begin(), b.end()); return a; }
static VV operator+(VV a, const V& b) { a.push_back(b); return a; }
static VV amp(double a, double d, double s, double r) { return {V("Amp Attack", a), V("Amp Decay", d), V("Amp Sustain", s), V("Amp Release", r)}; }
static VV e2(double a, double d, double s, double r) { return {V("Env2 Attack", a), V("Env2 Decay", d), V("Env2 Sustain", s), V("Env2 Release", r)}; }
static VV e3(double a, double d, double s, double r) { return {V("Env3 Attack", a), V("Env3 Decay", d), V("Env3 Sustain", s), V("Env3 Release", r)}; }
static VV f1(const char* type, double cut, double res, double env = 0, double key = 0, double drive = 0) { return {V("F1 Type", type), V("F1 Cutoff", cut), V("F1 Resonance", res), V("F1 Env Amount", env), V("F1 Key Track", key), V("F1 Drive", drive)}; }
static VV f2(const char* type, double cut, double res, const char* route = "Serial") { return {V("F2 Type", type), V("F2 Cutoff", cut), V("F2 Resonance", res), V("Filter Routing", route)}; }
static VV A(const char* wave, double level = 0.8, const char* oct = "0", const char* uni = "1", double det = 20, double spread = 0.6) { return {V("A Type", "Analog"), V("A Wave", wave), V("A Level", level), V("A Octave", oct), V("A Unison", uni), V("A Detune", det), V("A Spread", spread)}; }
static VV B(const char* wave, double level, const char* oct = "0", const char* uni = "1", double det = 20, double spread = 0.6, double fine = 0, double semi = 0) { return {V("B Type", "Analog"), V("B Wave", wave), V("B Level", level), V("B Octave", oct), V("B Unison", uni), V("B Detune", det), V("B Spread", spread), V("B Fine", fine), V("B Semi", semi)}; }
static VV AW(const char* table, double pos, double level = 0.8, const char* oct = "0", const char* uni = "1", double det = 15, double spread = 0.7) { return {V("A Type", "Wavetable"), V("A Table", table), V("A Position", pos), V("A Level", level), V("A Octave", oct), V("A Unison", uni), V("A Detune", det), V("A Spread", spread)}; }
static VV BW(const char* table, double pos, double level, const char* oct = "0", const char* uni = "1", double det = 15, double spread = 0.7) { return {V("B Type", "Wavetable"), V("B Table", table), V("B Position", pos), V("B Level", level), V("B Octave", oct), V("B Unison", uni), V("B Detune", det), V("B Spread", spread)}; }
static VV AF(double ratio, double index, double level = 0.8, double fb = 0, const char* oct = "0") { return {V("A Type", "FM"), V("A FM Ratio", ratio), V("A FM Index", index), V("A FM Feedback", fb), V("A Level", level), V("A Octave", oct)}; }
static VV BF(double ratio, double index, double level, double fb = 0, const char* oct = "0") { return {V("B Type", "FM"), V("B FM Ratio", ratio), V("B FM Index", index), V("B FM Feedback", fb), V("B Level", level), V("B Octave", oct)}; }
static VV mod(int n, const char* src, const char* dst, double amt) { std::string p = "Mod " + std::to_string(n) + " "; return {V((p + "Source").c_str(), src), V((p + "Target").c_str(), dst), V((p + "Amount").c_str(), amt)}; }
static VV lfo(int n, const char* shape, double rate, double fade = 0, bool retrig = true) { std::string p = "LFO" + std::to_string(n) + " "; return {V((p + "Shape").c_str(), shape), V((p + "Rate").c_str(), rate), V((p + "Fade In").c_str(), fade), V((p + "Retrigger").c_str(), retrig ? 1 : 0)}; }
static VV lfoSync(int n, const char* shape, const char* div) { std::string p = "LFO" + std::to_string(n) + " "; return {V((p + "Shape").c_str(), shape), V((p + "Sync").c_str(), 1), V((p + "Division").c_str(), div)}; }
static VV fx(double chorus, double delay, double reverb, const char* dtime = "1/8 .", double fb = 0.35, double size = 0.5, double decay = 2.5) { return {V("Chorus Mix", chorus), V("Delay Mix", delay), V("Delay Time", dtime), V("Delay Feedback", fb), V("Reverb Mix", reverb), V("Reverb Size", size), V("Reverb Decay", decay)}; }
static VV mono(double glide = 0, bool legato = false) { return {V("Play Mode", legato ? "Legato" : "Mono"), V("Glide", glide)}; }
static VV sub(double level, const char* wave = "Sine", const char* oct = "-1") { return {V("Sub Level", level), V("Sub Wave", wave), V("Sub Octave", oct)}; }
static VV noise(double level, double color = 0.5) { return {V("Noise Level", level), V("Noise Color", color)}; }
static VV arp(const char* mode, const char* rate, double gate, int oct = 1) { return {V("Arp On", 1), V("Arp Mode", mode), V("Arp Rate", rate), V("Arp Gate", gate), V("Arp Octaves", std::to_string(oct).c_str())}; }

